CREATE TABLE "Rol" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar UNIQUE NOT NULL
);

CREATE TABLE "Usuario" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar NOT NULL,
  "apellidos" varchar,
  "contrasena" varchar NOT NULL,
  "usuario" varchar UNIQUE NOT NULL,
  "email" varchar UNIQUE NOT NULL,
  "telefono" varchar,
  "area_asignada" varchar,
  "id_rol" integer NOT NULL
);

CREATE TABLE "Cadena" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar UNIQUE NOT NULL,
  "codigo" varchar UNIQUE NOT NULL
);

CREATE TABLE "Tienda" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "descripcion" varchar,
  "localidad" varchar,
  "domicilio" text,
  "c_postal" varchar,
  "zona_geografica" varchar,
  "id_cadena" integer NOT NULL,
  "id_capitan" integer
);

CREATE TABLE "Notificacion" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_usuario_destino" integer NOT NULL,
  "fecha_creacion" timestamp,
  "asunto" text NOT NULL,
  "mensaje" text NOT NULL
);

CREATE TABLE "Campana" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar NOT NULL,
  "ano" integer NOT NULL,
  "dia_comienzo" date NOT NULL,
  "dia_final" date NOT NULL
);

CREATE TABLE "Voluntario_Base" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "domicilio" text,
  "zona_geografica" varchar,
  "codigo_postal" varchar,
  "aprobado" boolean DEFAULT false
);

CREATE TABLE "Voluntario_Fisico" (
  "id_voluntario" integer PRIMARY KEY,
  "nombre" text,
  "apellidos" text,
  "id_coordinador" integer NOT NULL
);

CREATE TABLE "Voluntario_Entidad" (
  "id_voluntario" integer PRIMARY KEY,
  "nombre_asociacion" text,
  "n_voluntarios" integer,
  "id_responsable" integer NOT NULL
);

CREATE TABLE "Turno" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tipo_turno" varchar NOT NULL,
  "dia" date,
  "hora_inicio" time NOT NULL,
  "hora_fin" time NOT NULL,
  "id_campana" integer NOT NULL,
  "id_voluntario" integer NOT NULL,
  "id_tienda" integer NOT NULL
);

CREATE TABLE "Participa" (
  "id_campana" integer,
  "id_tienda" integer,
  "id_coordinador" integer,
  PRIMARY KEY ("id_campana", "id_tienda")
);

COMMENT ON TABLE "Campana" IS 'Las fechas de inicio deben ser anteriores a las de fin. Las campañas no se pueden superponer en el tiempo.';

ALTER TABLE "Usuario" ADD FOREIGN KEY ("id_rol") REFERENCES "Rol" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Tienda" ADD FOREIGN KEY ("id_cadena") REFERENCES "Cadena" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Tienda" ADD FOREIGN KEY ("id_capitan") REFERENCES "Usuario" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Notificacion" ADD FOREIGN KEY ("id_usuario_destino") REFERENCES "Usuario" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Voluntario_Fisico" ADD FOREIGN KEY ("id_voluntario") REFERENCES "Voluntario_Base" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Voluntario_Fisico" ADD FOREIGN KEY ("id_coordinador") REFERENCES "Usuario" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Voluntario_Entidad" ADD FOREIGN KEY ("id_voluntario") REFERENCES "Voluntario_Base" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Voluntario_Entidad" ADD FOREIGN KEY ("id_responsable") REFERENCES "Usuario" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Turno" ADD FOREIGN KEY ("id_campana") REFERENCES "Campana" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Turno" ADD FOREIGN KEY ("id_voluntario") REFERENCES "Voluntario_Base" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Turno" ADD FOREIGN KEY ("id_tienda") REFERENCES "Tienda" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Participa" ADD FOREIGN KEY ("id_campana") REFERENCES "Campana" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Participa" ADD FOREIGN KEY ("id_tienda") REFERENCES "Tienda" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Participa" ADD FOREIGN KEY ("id_coordinador") REFERENCES "Usuario" ("id") DEFERRABLE INITIALLY IMMEDIATE;
